  function acquisitionProgressOverview(section,entries){const label=locationSections.find(item=>item[0]===section)?.[1]||section,pokemon=entries.map(entry=>formByName.get(norm(entry.pokemon)));return locationSectionProgress(pokemon,label,`Unique Pokédex entries obtainable through ${label}`)}
  function wildUncaughtTable(entries){const q=norm(state.query),remaining=entries.filter(entry=>!state.caught.has(String(entry.pokemon.dexId))&&(!q||norm(displayPokemonName(entry.pokemon)).includes(q)||entry.encounters.some(source=>norm(source.location).includes(q)||norm(source.method).includes(q))));return`<section class="wild-uncaught-list"><header><div><span class="eyebrow">ONE-PAGE CATCH LIST</span><h2>Uncaught wild Pokémon</h2><p>Ordered by the earliest listed location: numerical routes first, then all other locations alphabetically.</p></div><strong>${remaining.length} remaining</strong></header><div class="wild-uncaught-table" role="table" aria-label="Uncaught wild Pokémon"><div class="wild-uncaught-head" role="row"><span role="columnheader">Pokémon</span><span role="columnheader">Locations and encounter details</span><span role="columnheader">Caught</span></div>${remaining.map(entry=>{const p=entry.pokemon;return`<article class="wild-uncaught-row" role="row"><button class="wild-uncaught-pokemon" data-encounter-pokemon="${p.id}" role="cell"><img src="${p.sprite}" alt=""><span><strong>${esc(displayPokemonName(p))}</strong><small>#${String(p.dexId).padStart(4,'0')} · ${p.bst} BST</small>${types(p)}${rankBadges(p)}</span></button><div class="wild-uncaught-sources" role="cell">${entry.encounters.map(source=>`<button data-pokemon-location="${esc(source.location)}" data-location-period="${source.periodKey}"><strong>${esc(source.location)}</strong><span>${esc(source.period)} · ${esc(source.method)}${source.level?` · Lv. ${esc(source.level)}`:''}${source.rarity!=null?` · ${source.rarity}%`:''}</span></button>`).join('')}</div><button class="caught-ball" data-caught="${p.dexId}" title="Mark caught" aria-label="Mark ${esc(displayPokemonName(p))} as caught"><img src="assets/ui/pokeball.svg" alt=""></button></article>`}).join('')||'<p class="wild-uncaught-empty">No uncaught wild Pokémon match this search.</p>'}</div></section>`}
  function encounterMethod(entry,section){const method=entry.method||'';if(section==='raids')return['Raid Encounters','Raid Den Pokémon'];if(/surf/i.test(method))return['Surfing','Surf encounters'];if(/rod|fish/i.test(method))return['Fishing','Fishing encounters'];return[section==='safari'?'Wild Encounters':'Grass / Cave',section==='safari'?'Grass encounters':'Grass and cave encounters']}
  function encounterSubsections(entries,renderer,section='wild'){const groups=new Map();entries.forEach(entry=>{const [key,label]=encounterMethod(entry,section);if(!groups.has(key))groups.set(key,{label,entries:[]});groups.get(key).entries.push(entry)});const order=section==='raids'?['Raid Encounters']:section==='safari'?['Wild Encounters','Surfing','Fishing']:['Grass / Cave','Surfing','Fishing'];return order.filter(key=>groups.has(key)).map(key=>{const group=groups.get(key);return`<section class="encounter-method-group"><header><div><span>${esc(group.label)}</span><h3>${esc(key)}</h3></div><b>${group.entries.length}</b></header><div>${group.entries.map(renderer).join('')}</div></section>`}).join('')}
  function renderWildLocations(){const q=norm(state.query),allPlaces=wildLocations(),wildIndex=wildEncounterIndex(allPlaces),places=state.locationFilter?allPlaces.filter(x=>x.name===state.locationFilter):allPlaces.filter(x=>!q||norm(x.name).includes(q)||x[state.period].some(e=>norm(e.pokemon).includes(q)||norm(e.method).includes(q))),visiblePlaces=state.locationFilter?places:places.slice(0,state.locationVisible),quickFilters=`<nav class="location-quick-filters" aria-label="Quick location filters"><button data-location-filter="" class="${!state.locationFilter&&!state.wildUncaughtView?'active':''}">All</button>${allPlaces.map(place=>`<button data-location-filter="${esc(place.name)}" class="${!state.wildUncaughtView&&state.locationFilter===place.name?'active':''}">${esc(place.name)}</button>`).join('')}</nav>`,progress=wildProgressOverview(wildIndex);if(state.wildUncaughtView)return`${locationControls(false,true,true)}${quickFilters}${progress}${wildUncaughtTable(wildIndex)}`;return`${locationControls(true,true,true)}${quickFilters}${progress}<section class="location-grid">${visiblePlaces.map(place=>{const encounters=visibleLocationEncounters(place),mapped=atlasPosition(place.name),allEncounters=[...place.day,...place.night];return`<article class="location-panel" data-location="${esc(norm(place.name))}"><header><div><span>${state.period.toUpperCase()} ENCOUNTERS</span><h2>${esc(place.name)}</h2></div><div class="location-panel-actions">${locationProgress(allEncounters)}${mapped?`<button data-open-map="${esc(place.name)}">Open Map</button>`:''}</div></header><div class="location-methods">${encounters.length?encounterSubsections(encounters,encounterCard,'wild'):`<p class="empty small">${state.hideCaught?'All documented encounters caught.':'No encounters listed for this time.'}</p>`}</div></article>`}).join('')}</section>${visiblePlaces.length<places.length?'<div id="locationLoadSentinel" class="load-sentinel">Loading more locations…</div>':''}`}
  function acquisitionCard(entry,showCaught=true){const p=formByName.get(norm(entry.pokemon)),caught=p&&state.caught.has(String(p.dexId));return`<article class="acquisition-row ${p?'interactive':''}" ${p?`data-encounter-pokemon="${p.id}" role="button" tabindex="0"`:''}>${p?`<img src="${p.sprite}" alt="">`:''}<div><strong>${esc(locationPokemonName(entry.pokemon))}</strong><span>${esc(entry.method||'Acquisition')}</span>${entry.details?`<p>${esc(entry.details)}</p>`:''}${p?`<span class="encounter-bst">${p.bst} BST</span>${rankBadges(p)}`:''}</div><aside>${entry.level?`<small>Lv. ${esc(entry.level)}</small>`:''}${entry.rarity!=null?`<b>${entry.rarity}%</b>`:''}${entry.cost?`<b>${esc(entry.cost)}</b>`:''}${p&&showCaught?`<button class="caught-ball ${caught?'caught':''}" data-caught="${p.dexId}" title="${caught?'Mark not caught':'Mark caught'}"><img src="assets/ui/pokeball.svg" alt=""></button>`:''}</aside></article>`}
