  function renderLocations(){let content=state.locationSection==='wild'?renderWildLocations():state.locationSection==='legendaries'?renderLegendaries(true):state.locationSection==='eggs'?renderEggs(true):renderAcquisitionLocations(state.locationSection);return`<header class="page-head"><div><span class="eyebrow">COMPLETE ACQUISITION ATLAS</span><h1>Locations</h1><p>Every documented way to obtain Pokémon in Radical Red v4.1.</p></div></header>${locationSectionNav()}${content}`; }
  function saveTeam(){localStorage.setItem(syncKeys.team,JSON.stringify(state.team));state.saveMeta.revision++;state.saveMeta.modifiedAt=new Date().toISOString();localStorage.setItem(syncKeys.meta,JSON.stringify(state.saveMeta));state.syncSnapshot=null;state.syncStatus=state.syncCode&&syncEndpoint?'local-newer':'unchecked'}
  function teamMoves(p){return [...new Set(moveLearningForms(p).flatMap(form=>[...(form.learnset?.level||[]).map(x=>x.moveId),...(form.learnset?.tm||[]),...(form.learnset?.tutor||[])]))].map(id=>moveById.get(Number(id))).filter(Boolean).sort((a,b)=>a.name.localeCompare(b.name))}
