  function battleRecommendations(){return state.battle.map((enemySlot,enemyIndex)=>{const enemy=pokemonById.get(Number(enemySlot.pokemonId));if(!enemy)return null;const known=enemyMoves(enemySlot,enemy),moves=known.length?new Map([[enemy.id,known]]):null,recommendations=state.team.map((slot,index)=>recommendationFor(slot,index,[enemy],moves)).filter(Boolean).sort((a,b)=>b.rating-a.rating);return{enemy,enemyIndex,recommendations}}).filter(Boolean)}
