  function supportMoveScore(move){const text=norm(`${move.name} ${move.description}`);let score=10;[['recover heal restore roost synthesis wish drain',32],['protect reflect lightscreen auroraveil substitute',25],['stealthrock spikes toxicspikes stickyweb',24],['burn poison paralyze sleep confusion status',22],['raise boost attack defense speed evas',18],['lower reduce intimidate disable taunt encore',17],['weather terrain tailwind trickroom',14]].forEach(([words,value])=>{if(words.split(' ').some(word=>text.includes(norm(word))))score+=value});return score}
