  const curatedBuildData=window.CURATED_BUILD_DATA||{meta:{},builds:[]},curatedPokemonAliases={cincinno:'cinccino',darmanitangalarz:'darmanitangalarzen',jellicentmale:'jellicent',pyroarmale:'pyroar',terapagos:'terapagosterastal',unfezantmale:'unfezant',urshifusingle:'urshifu'},curatedMoveByName=new Map((data.moves||[]).map(move=>[norm(move.name),move]));
