  function enhanceFuturePickers(root){root.querySelectorAll('[data-future-species]').forEach(input=>{input.classList.add('pokemon-picker-input');const close=()=>input.parentElement?.querySelector('.pokemon-picker-results')?.remove(),show=()=>{close();const q=norm(input.value);if(!q)return;const matches=teamPokemonChoices.filter(p=>norm(displayPokemonName(p)).includes(q)).sort((a,b)=>(norm(displayPokemonName(a)).startsWith(q)?0:1)-(norm(displayPokemonName(b)).startsWith(q)?0:1)||displayPokemonName(a).localeCompare(displayPokemonName(b))).slice(0,8),results=document.createElement('div');results.className='pokemon-picker-results';results.innerHTML=matches.map(p=>`<button type="button" data-future-pick="${p.id}"><img src="${p.sprite}" alt=""><span><strong>${esc(displayPokemonName(p))}</strong>${types(p)}</span></button>`).join('')||'<p>No matching Pokémon.</p>';input.insertAdjacentElement('afterend',results);results.querySelectorAll('[data-future-pick]').forEach(button=>button.onmousedown=event=>{event.preventDefault();input.value=displayPokemonName(pokemonById.get(Number(button.dataset.futurePick)));close();input.dispatchEvent(new Event('change',{bubbles:true}))})};input.oninput=show;input.onfocus=()=>{if(input.value.trim())show()};input.onblur=()=>setTimeout(close,150)})}
