  function openPokemon(id){ const p=pokemonById.get(Number(id)); if(!p)return; const key=String(p.dexId), caught=state.caught.has(key), labels=['HP','Attack','Defense','Speed','Sp. Atk','Sp. Def'], from=evolutionLinks(p,'from'), to=evolutionLinks(p,'to'), locations=pokemonLocations(p), group=groups.find(item=>item.dexId===key); dialog.querySelector('#dialogContent').innerHTML=`<div class="dialog-actions"><button class="caught-ball detail-caught ${caught?'caught':''}" data-caught="${key}" title="${caught?'Mark not caught':'Mark caught'}" aria-label="${caught?'Caught':'Not caught'}"><img src="assets/ui/pokeball.svg" alt=""></button><button class="dialog-close" aria-label="Close">×</button></div><div class="detail-hero" style="--accent:${p.typeColours[0]}"><img src="${p.sprite}" alt=""><div><span class="eyebrow">#${String(p.dexId).padStart(4,'0')}</span><h2>${esc(displayPokemonName(p))}</h2>${types(p)}<strong>${p.bst} BST</strong>${group&&group.forms.length>1?`<div class="detail-form-row" data-current-id="${p.id}"><button data-detail-step="-1" data-detail-group="${key}" aria-label="Previous form">‹</button><span>${esc(formName(group,p))}</span><button data-detail-step="1" data-detail-group="${key}" aria-label="Next form">›</button></div>`:''}</div></div>${formChangeSection(group,p)}<section class="stats">${p.stats.map((v,i)=>`<div><span>${labels[i]}</span><b>${v}</b><i><em style="width:${Math.min(100,v/1.55)}%"></em></i></div>`).join('')}</section><section class="abilities"><h3>Abilities</h3>${p.abilities.map(a=>`<article><b>${esc(a.name)}</b><p>${esc(a.description||'No description available.')}</p></article>`).join('')}</section>${pokemonMovesSection(p)}<section class="evolutions"><h3>Evolution family</h3>${evolutionSection('Evolves from',from)}${evolutionSection('Evolves to',to)}</section>${locationSection(locations,p)}`; dialog.showModal(); dialog.querySelector('.dialog-close').onclick=()=>dialog.close(); bind(dialog); }
